 "caveats": [
  "西交A/B名单为旧版不完整名单(2页/19项), 标「未认定(待核)」不代表学校未认定。",
  "电气相关度为 AI 初判, 需人工复核(改 data/curated/ee_relevance.json)。",
  "报名截止时间未结构化收录, 需人工维护; 通知标题与竞赛的关联为关键词自动匹配, 可能有误。",
  "年度节律是从历史通知统计推断的窗口, 不是官方赛程, 仅表示往年在这些月份发过通知。"
 ]
